import type { WorkflowStepContext, MutationContext } from "apps";
import { configuration } from "./configuration.ts";
import { requirements, origin } from "./installation.ts";

type Context = WorkflowStepContext<typeof requirements> | MutationContext<typeof requirements>;
export class ReadUnavailable extends Error {
  constructor(
    readonly status: number,
    readonly reason?: string,
  ) {
    super("The permitted source request did not succeed.");
  }
}
export const record = (value: unknown): Record<string, unknown> | undefined =>
  typeof value === "object" && value !== null && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : undefined;
export const list = (value: unknown) => (Array.isArray(value) ? value : []);
export const text = (value: unknown) => (typeof value === "string" ? value : undefined);
export const numeric = (value: unknown) =>
  typeof value === "number" && Number.isFinite(value) ? value : undefined;
export const instant = (value: unknown) => {
  const result = typeof value === "string" ? Date.parse(value) : numeric(value);
  return result !== undefined && Number.isFinite(result) ? result : undefined;
};
export function organization(context: Context) {
  const account = context.user.accounts.service;
  const selected =
    account.method === "apiKey" ? account.fields.organization : configuration.organization;
  if (!selected || (configuration.organization && configuration.organization !== selected))
    throw new ReadUnavailable(0);
  return selected;
}
/** Raw responses stay inside a read/send callback, before its allowlisted result is journaled. */
export async function api(
  context: Context,
  method: string,
  path: string,
  input?: unknown,
): Promise<unknown> {
  const account = context.user.accounts.service;
  const token = account.method === "apiKey" ? account.fields.token : account.fields.access_token;
  const headers = new Headers({ authorization: `Bearer ${token}`, accept: "application/json" });
  if (account.method === "apiKey") headers.set("X-Executor-Organization", organization(context));
  if (input !== undefined) headers.set("Content-Type", "application/json");
  const url = new URL(
    `/api/organizations/${encodeURIComponent(organization(context))}/${path}`,
    origin,
  );
  const response = await context.fetch(url, {
    method,
    headers,
    redirect: "manual",
    signal: AbortSignal.any([context.signal, AbortSignal.timeout(10000)]),
    ...(input === undefined ? {} : { body: JSON.stringify(input) }),
  });
  if (!response.ok) {
    let reason: string | undefined;
    try {
      reason = text(record(await response.json())?._tag);
    } catch {
      /* No failure body is retained. */
    }
    throw new ReadUnavailable(response.status, reason);
  }
  return response.json();
}
export function tool(
  context: Context,
  selected: { app: string; tool: string; input: unknown },
  kind: "query" | "mutation" = "query",
) {
  return api(context, "POST", `apps/${encodeURIComponent(selected.app)}/tools/call`, {
    tool: selected.tool,
    kind,
    input: selected.input,
  });
}
export function accountLink(context: Context, id: string) {
  return new URL(
    `/org/${encodeURIComponent(organization(context))}/accounts?account=${encodeURIComponent(id)}`,
    origin,
  ).href;
}
export function appLink(context: Context, app: string) {
  return new URL(
    `/org/${encodeURIComponent(organization(context))}/apps/${encodeURIComponent(app)}`,
    origin,
  ).href;
}

import { emptyCheckpoint, type Checkpoint, type Observation } from "./types.ts";
export interface ConnectionFact {
  id: string;
  at: number;
  current: boolean;
  status: string;
  canManage: boolean;
  canReconnect: boolean;
  checkable: boolean;
}
export function connectionObservation(fact: ConnectionFact): Observation {
  const definitive = fact.current && fact.checkable;
  const code =
    definitive && fact.canReconnect && fact.status === "credentials_rejected"
      ? "reconnect-required"
      : definitive && fact.canManage && fact.status === "forbidden"
        ? "permission-required"
        : definitive && fact.status === "healthy"
          ? "connection-healthy"
          : "connection-unknown";
  return {
    cursor: `${fact.id}:${fact.at}:${fact.status}`,
    at: fact.at,
    verdict:
      code === "connection-healthy"
        ? "healthy"
        : code === "connection-unknown"
          ? "unknown"
          : "action",
    code,
    failures: 0,
    successes: 0,
    since: fact.at,
  };
}
export interface PoolFact {
  at: number;
  owner: boolean;
  provider: string;
  accounts: Array<{
    id: string;
    state: string;
    fresh: boolean;
    failed: boolean;
    windows: Array<{
      id: string;
      remaining: number | null;
      observedAt: number | null;
      resetAt: number | null;
    }>;
  }>;
}
export function poolObservation(fact: PoolFact, previous = emptyCheckpoint()): Observation {
  const accounts = fact.accounts.filter((account) => account.state !== "disabled");
  const valid =
    fact.owner &&
    accounts.length > 0 &&
    accounts.every(
      (account) =>
        account.state === "active" &&
        account.fresh &&
        !account.failed &&
        account.windows.length > 0 &&
        account.windows.every(
          (window) =>
            window.remaining !== null &&
            window.remaining >= 0 &&
            window.remaining <= 1 &&
            window.observedAt !== null &&
            window.observedAt <= fact.at &&
            fact.at - window.observedAt <= 30 * 60000 &&
            window.resetAt !== null &&
            window.resetAt > fact.at,
        ),
    );
  // An unchanged account reading never confirms another scan, even if another account refreshed.
  const readings = accounts
    .flatMap((account) =>
      account.windows.map((window) => `${account.id}:${window.id}:${window.observedAt}`),
    )
    .sort();
  const prior = previous.observation;
  const cursor = readings.join("|");
  const allLow =
    valid &&
    accounts.every((account) => account.windows.some((window) => window.remaining! <= 0.1));
  const allHigh =
    valid &&
    accounts.every((account) => account.windows.every((window) => window.remaining! > 0.2));
  const priorReadings = new Set((prior.confirmationCursor ?? "").split("|"));
  const independentlyFresh =
    readings.length > 0 && readings.every((reading) => !priorReadings.has(reading));
  const failure =
    allLow && independentlyFresh ? prior.failures + 1 : !valid || allLow ? prior.failures : 0;
  const success =
    allHigh && independentlyFresh ? prior.successes + 1 : !valid || allHigh ? prior.successes : 0;
  const opening = valid && allLow && failure >= 2;
  const closing = valid && allHigh && success >= 2;
  const exhausted =
    allLow && accounts.every((account) => account.windows.some((window) => window.remaining === 0));
  return {
    cursor: cursor || `unknown:${fact.at}`,
    at: fact.at,
    verdict: opening ? "action" : closing ? "healthy" : "unknown",
    code: !valid
      ? "quota-unknown"
      : opening
        ? exhausted
          ? "pool-exhausted"
          : "pool-low"
        : "confirming-quota",
    failures: failure,
    successes: success,
    since: prior.since || fact.at,
    ...(valid && independentlyFresh && (allLow || allHigh)
      ? { confirmationCursor: cursor }
      : prior.confirmationCursor === undefined
        ? {}
        : { confirmationCursor: prior.confirmationCursor }),
  };
}
export function quietAt(
  at: number,
  hours: null | { timezone: string; startHour: number; endHour: number },
) {
  if (hours === null) return false;
  const hour = Number(
    new Intl.DateTimeFormat("en", {
      timeZone: hours.timezone,
      hourCycle: "h23",
      hour: "numeric",
    }).format(at),
  );
  return hours.startHour <= hours.endHour
    ? hour >= hours.startHour && hour < hours.endHour
    : hour >= hours.startHour || hour < hours.endHour;
}

import { configuration } from "./configuration.ts";
/** Consent binds to this pinned source's configuration, including its channel input formatter. */
export async function configurationRevision() {
  const encoded = JSON.stringify(configuration, (_key, value: unknown) =>
    typeof value === "function" ? value.toString() : value,
  );
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(encoded));
  return Array.from(new Uint8Array(digest), (byte) => byte.toString(16).padStart(2, "0")).join("");
}

/** Edit this private copy, then approve its delivery setting and enable its native schedule. */
export const configuration = {
  organization: "",
  /** The existing connected channel app and its exact send tool. No default recipient. */
  channel: null as null | {
    app: string;
    tool: string;
    input: (message: string, reviewUrl: string) => Record<string, unknown>;
    receipt: (result: unknown) => string | undefined;
  },
  quietHours: null as null | { timezone: string; startHour: number; endHour: number },
  /** Empty watches all personal, checkable accounts returned by the authorized inventory. */
  accounts: [] as string[],
  /** Provider IDs come from the pool's view. No provider or plan assumptions are made here. */
  pools: [] as Array<{ app: string; provider: string }>,
  operator: {
    release: null as null | {
      app: string;
      tool: string;
      input: Record<string, unknown>;
      workflowId: number;
      branch: string;
      repository: string;
    },
    availability: null as null | { publicUrl: string },
    workflowApps: [] as string[],
    /** Supply these reads only after verifying a permitted connector's actual metric contract. */
    runtime: null as null | { app: string; tool: string; input: Record<string, unknown> },
    httpErrors: null as null | { app: string; tool: string; input: Record<string, unknown> },
    errorCounts: null as null | { app: string; tool: string; input: Record<string, unknown> },
  },
};

import {
  boolean,
  mutation,
  number,
  object,
  query,
  string,
  type MutationContext,
  type QueryContext,
} from "apps";
import { always } from "apps/operations/approval";
import { configurationRevision } from "./configuration-revision.ts";
import { requirements } from "./installation.ts";
import { controls, write } from "./state.ts";
type Writer = MutationContext<typeof requirements>;
const keyInput = object({ key: string() });
export const configure = mutation(
  {
    description:
      "Set up this private copy. Delivery remains off unless explicitly enabled. Pausing a schedule stops new scans; turn delivery off or terminate its runs to stop current ones.",
    input: object({ deliveryEnabled: boolean() }),
    approval: always(),
  },
  async (ctx: Writer, input) => {
    const revision = await configurationRevision();
    return ctx.sql.transaction((tx) => {
      if (ctx.user.id === undefined) throw new Error("A personal identity is required.");
      const current = tx
        .exec<{ owner: string | null }>("SELECT owner FROM controls WHERE id = 1")
        .one();
      if (current.owner !== null && current.owner !== ctx.user.id)
        throw new Error("Use your own private copy.");
      tx.exec(
        "UPDATE controls SET owner = ?, configuration_revision = ?, delivery_enabled = ? WHERE id = 1",
        ctx.user.id,
        revision,
        input.deliveryEnabled ? 1 : 0,
      );
      return { deliveryEnabled: input.deliveryEnabled, revision };
    });
  },
);
export const settings = query(
  { input: object({}) },
  async (ctx: QueryContext<typeof requirements>) => {
    const current = controls(ctx);
    return {
      deliveryEnabled: current.delivery_enabled === 1,
      revision: current.configuration_revision,
      current: current.configuration_revision === (await configurationRevision()),
    };
  },
);
export const mute = mutation(
  {
    approval: undefined,
    description: "Snooze this resource until the supplied UTC time. Use unmute to reverse it.",
    input: object({ key: string(), until: number() }),
  },
  async (ctx: Writer, input) =>
    write(ctx, input.key, (current) => ({
      ...current,
      revision: current.revision + 1,
      mutedUntil: input.until,
    })),
);
export const unmute = mutation(
  { approval: undefined, input: keyInput },
  async (ctx: Writer, input) =>
    write(ctx, input.key, (current) => ({
      ...current,
      revision: current.revision + 1,
      mutedUntil: 0,
    })),
);
export const retryRefusedDelivery = mutation(
  {
    description:
      "Retry only a known pre-submission refusal. Uncertain or accepted sends need provider reconciliation and cannot be retried here.",
    input: keyInput,
    approval: always(),
  },
  async (ctx: Writer, input) =>
    write(ctx, input.key, (current) => {
      if (current.notified !== "refused")
        throw new Error("There is no known safe refused delivery to retry.");
      return { ...current, revision: current.revision + 1, notified: "none" };
    }),
);
export const controlTools = { configure, settings, mute, unmute, retryRefusedDelivery };

import type { WorkflowContext, WorkflowStepContext } from "apps";
import { configurationRevision } from "./configuration-revision.ts";
import { configuration } from "./configuration.ts";
import { api, ReadUnavailable, record, text, tool } from "./api.ts";
import { requirements } from "./installation.ts";
import { quietAt } from "./conditions.ts";
import { claimNudge, deliveryResult } from "./storage.ts";
import type { Checkpoint, Observation } from "./types.ts";
type Flow = WorkflowContext<typeof requirements>;
type Step = WorkflowStepContext<typeof requirements>;
export type ReadAgain = (step: Step, previous: Checkpoint) => Promise<Observation>;
const noRetry = { retries: { limit: 0, delay: "1 second" }, timeout: "15 seconds" } as const;
/** These are pre-execution API refusals. A tool's own error may follow a successful side effect. */
const beforeSubmission = new Set([
  "OrganizationForbidden",
  "ToolBlocked",
  "ToolApprovalRequired",
  "ToolNotFound",
  "ToolKindMismatch",
  "InputInvalid",
  "AccountRequired",
  "AccountNotFound",
  "OAuthReconnectRequired",
  "ToolPolicyFailed",
]);
async function pending(step: Step, question: NonNullable<Checkpoint["question"]>) {
  let after = "";
  while (true) {
    const page = record(
      await api(
        step,
        "GET",
        `workflow-inputs?pending=true${after ? `&after=${encodeURIComponent(after)}` : ""}`,
      ),
    );
    const values = page?.items;
    if (!Array.isArray(values)) return false;
    if (
      values.some((value) => {
        const input = record(value);
        return input?.id === question.id && input.app === question.app;
      })
    )
      return true;
    const next = text(page?.next);
    if (!next || next <= after) return false;
    after = next;
  }
}
export async function nudge(ctx: Flow, key: string, previous: Checkpoint, readAgain: ReadAgain) {
  const question = previous.question;
  if (!question || previous.notified !== "none" || configuration.channel === null)
    return "already-notified";
  const observation = await ctx.step.do("recheck before nudge", (step) =>
    readAgain(step, previous),
  );
  const deliveryAt = await ctx.step.do("delivery clock", async () => Date.now());
  if (observation.verdict !== "action" || quietAt(deliveryAt, configuration.quietHours))
    return "deferred";
  const claimed = await ctx.step.runMutation("claim one nudge", claimNudge, {
    key,
    episode: previous.episode,
    question: question.id,
    now: deliveryAt,
  });
  if (!claimed) return "deferred";
  const result = await ctx.step.do("send configured nudge", noRetry, async (step) => {
    // The provider may accept a send even when its HTTP response or workflow receipt is lost.
    try {
      const consent = record(await tool(step, { app: question.app, tool: "settings", input: {} }));
      const latest = record(
        await tool(step, { app: question.app, tool: "checkpoint", input: { key } }),
      );
      if (
        consent?.deliveryEnabled !== true ||
        consent.revision !== (await configurationRevision()) ||
        latest?.open !== true ||
        record(latest.question)?.id !== question.id ||
        typeof latest.mutedUntil !== "number" ||
        latest.mutedUntil > Date.now()
      )
        return { status: "refused" };
      if (
        !(await pending(step, question)) ||
        (await readAgain(step, previous)).verdict !== "action"
      )
        return { status: "refused" };
      const channel = configuration.channel;
      if (channel === null) return { status: "refused" };
      const result = await tool(
        step,
        {
          app: channel.app,
          tool: channel.tool,
          input: channel.input("A workflow needs your input.", question.reviewUrl),
        },
        "mutation",
      );
      const receipt = channel.receipt(result);
      return receipt && /^[a-zA-Z0-9_.:-]{1,200}$/.test(receipt)
        ? { status: "sent", receipt }
        : { status: "uncertain" };
    } catch (error) {
      return {
        status:
          error instanceof ReadUnavailable &&
          error.reason !== undefined &&
          beforeSubmission.has(error.reason)
            ? "refused"
            : "uncertain",
      };
    }
  });
  await ctx.step.runMutation("save delivery receipt", deliveryResult, {
    key,
    episode: previous.episode,
    ...result,
  });
  return result.status === "uncertain"
    ? "delivery-uncertain"
    : result.status === "refused"
      ? "delivery-refused"
      : "sent";
}

import type { WorkflowContext } from "apps";
import { api, record, text } from "./api.ts";
import { requirements } from "./installation.ts";
import { nudge, type ReadAgain } from "./delivery.ts";
import {
  attachQuestion,
  checkpoint,
  claimQuestion,
  disposition,
  saveObservation,
  settings,
} from "./storage.ts";
import type { Checkpoint, Observation } from "./types.ts";

type Flow = WorkflowContext<typeof requirements>;
export const clock = (ctx: Flow, name: string) => ctx.step.do(name, async () => Date.now());
export async function withdraw(
  ctx: Flow,
  question: NonNullable<Checkpoint["question"]>,
  label: string,
) {
  return ctx.step.do(label, async (step) => {
    await api(
      step,
      "POST",
      `apps/${encodeURIComponent(question.app)}/workflow-inputs/${encodeURIComponent(question.id)}/withdraw`,
    );
    return { status: "withdrawn" };
  });
}
/** Native pages perform the repair. A saved form response only asks this workflow to verify it. */
const evidenceFor = (observation: Observation) => [
  { label: "Condition", value: observation.code },
  { label: "Observed at", value: new Date(observation.at).toISOString() },
  ...(observation.attemptedSha
    ? [{ label: "Attempted commit", value: observation.attemptedSha }]
    : []),
];
export async function ask(
  ctx: Flow,
  key: string,
  previous: Checkpoint,
  readAgain: ReadAgain,
  link: string,
  label: string,
) {
  const now = await clock(ctx, "question clock");
  const claim = await ctx.step.runMutation("claim question", claimQuestion, {
    key,
    episode: previous.episode,
    run: ctx.runId,
    now,
  });
  if (!claim.owned)
    return {
      status: await nudge(ctx, key, claim.state, readAgain),
      code: claim.state.observation.code,
    };
  const question = await ctx.step.requestInput("review resource", {
    timeoutMs: 7 * 86400000,
    evidence: evidenceFor(claim.state.observation),
    form: {
      mode: "form",
      message: `${label}. Condition: ${claim.state.observation.code}. Observed ${new Date(claim.state.observation.at).toISOString()}. Open the existing page to act, then recheck. Saving an answer does not fix the resource.`,
      requestedSchema: {
        type: "object",
        properties: {
          action: { type: "string", enum: ["recheck", "defer"], title: "Next step" },
          minutes: {
            type: "integer",
            minimum: 1,
            maximum: 10080,
            default: 60,
            title: "Minutes to defer",
          },
        },
        required: ["action"],
      },
    },
    links: [
      { label: "Open resource", href: link },
      ...(claim.state.observation.evidenceUrl
        ? [{ label: "Open evidence", href: claim.state.observation.evidenceUrl }]
        : []),
    ],
  });
  if (!question.reviewUrl) throw new Error("This host has no authenticated workflow review route.");
  const attached = await ctx.step.runMutation("attach waiting question", attachQuestion, {
    key,
    episode: claim.state.episode,
    run: ctx.runId,
    id: question.id,
    app: question.app,
    reviewUrl: question.reviewUrl,
  });
  const reference = {
    id: question.id,
    app: question.app,
    reviewUrl: question.reviewUrl,
    run: ctx.runId,
  };
  if (!attached) {
    await withdraw(ctx, reference, "withdraw obsolete question");
    return { status: "obsolete" };
  }
  const state = await ctx.step.runQuery("current waiting state", checkpoint, { key });
  const delivery = await nudge(ctx, key, state, readAgain);
  const response = await ctx.step.waitForInput("wait for the owner", question);
  const answeredAt = await clock(ctx, "answer clock");
  const declined = response.status === "answered" && response.response.action !== "accept";
  const minutes =
    response.status === "answered" &&
    response.response.action === "accept" &&
    response.response.content?.action === "defer"
      ? Number(response.response.content.minutes ?? 60)
      : 0;
  if (response.status !== "answered" || declined || minutes > 0) {
    await ctx.step.runMutation("record decision", disposition, {
      key,
      episode: state.episode,
      run: ctx.runId,
      declined,
      mutedUntil: minutes > 0 ? answeredAt + minutes * 60000 : 0,
    });
    return {
      status: response.status !== "answered" ? response.status : declined ? "declined" : "deferred",
      delivery,
    };
  }
  const currentSettings = await ctx.step.runQuery("settings after answer", settings, {});
  if (!currentSettings.current) return { status: "configuration-changed", delivery };
  const current = await ctx.step.runQuery("state after answer", checkpoint, { key });
  if (!current.open || current.episode !== state.episode) return { status: "obsolete", delivery };
  const verified = await ctx.step.do("verify the resource", (step) => readAgain(step, current));
  const saved = await ctx.step.runMutation("remember verification", saveObservation, {
    key,
    revision: current.revision,
    ...verified,
  });
  if (saved.withdrawn) await withdraw(ctx, saved.withdrawn, "withdraw recovered verification");
  await ctx.step.runMutation("finish verification", disposition, {
    key,
    episode: state.episode,
    run: ctx.runId,
    declined: false,
    mutedUntil: 0,
  });
  return {
    status:
      verified.verdict === "withdraw"
        ? "withdrawn"
        : !saved.state.open
          ? "healthy"
          : "still-needs-action",
    code: saved.state.observation.code,
    delivery,
  };
}
export async function observe(
  ctx: Flow,
  key: string,
  readAgain: ReadAgain,
  link: string,
  label: string,
) {
  const currentSettings = await ctx.step.runQuery("check private ownership", settings, {});
  if (!currentSettings.current) return { status: "unconfigured", code: "configuration-changed" };
  const previous = await ctx.step.runQuery("previous observation", checkpoint, { key });
  const observation = await ctx.step.do("read current facts", (step) => readAgain(step, previous));
  const { state, withdrawn } = await ctx.step.runMutation(
    "remember current facts",
    saveObservation,
    { key, revision: previous.revision, ...observation },
  );
  if (withdrawn) await withdraw(ctx, withdrawn, "withdraw recovered question");
  if (state.open && state.question)
    await ctx.step.do("update waiting evidence", async (step) => {
      const updated = record(
        await api(
          step,
          "POST",
          `apps/${encodeURIComponent(state.question!.app)}/workflow-inputs/${encodeURIComponent(state.question!.id)}/evidence`,
          { evidence: evidenceFor(state.observation) },
        ),
      );
      return { status: text(updated?.status) ?? "unknown" };
    });
  if (!state.open)
    return {
      status:
        observation.verdict === "healthy"
          ? "healthy"
          : observation.verdict === "withdraw"
            ? "withdrawn"
            : "unknown",
      code: observation.code,
    };
  if (observation.verdict !== "action") return { status: "unknown", code: observation.code };
  return ask(ctx, key, state, readAgain, link, label);
}

import { defineProvider, object, string, secrets, oauth2 } from "apps";

export const origin = "https://app.signalbox.run";
// Match the installation's existing management provider so its native account can be linked.
export const provider = defineProvider({
  name: "Signalbox",
  auth: {
    apiKey: secrets({
      label: "Signalbox API key",
      fields: object({ token: string(), organization: string() }),
    }),
    oauth: oauth2({ discover: `${origin}/api` }),
  },
});
export const requirements = { user: { accounts: { service: provider } } };

import type { WorkflowStepContext, MutationContext } from "apps";
import { requirements } from "./installation.ts";
import { api, instant, list, numeric, ReadUnavailable, record, text, tool } from "./api.ts";
import { configuration } from "./configuration.ts";
import { connectionObservation, poolObservation, type PoolFact } from "./conditions.ts";
import type { Checkpoint, Observation } from "./types.ts";
type Step = WorkflowStepContext<typeof requirements>;
const unknown = (at: number, code: string): Observation => ({
  cursor: `${code}:${at}`,
  at,
  verdict: "unknown",
  code,
  failures: 0,
  successes: 0,
  since: at,
});

export async function connectionTargets(context: MutationContext<typeof requirements>) {
  if (configuration.accounts.length) return [...new Set(configuration.accounts)];
  const inventory = record(await api(context, "GET", "inventory"));
  return list(inventory?.accounts).flatMap((value) => {
    const account = record(value),
      health = record(account?.health);
    return typeof account?.id === "string" &&
      list(health?.apps).some((entry) => record(entry)?.checkable === true)
      ? [account.id]
      : [];
  });
}
export async function readConnection(context: Step, id: string): Promise<Observation> {
  const now = Date.now();
  try {
    const detail = record(await api(context, "GET", `accounts/${encodeURIComponent(id)}`));
    if (detail?.canReconnect !== true && detail?.canManage !== true)
      return { ...unknown(now, "not-connection-owner"), verdict: "withdraw" };
    await api(context, "POST", `accounts/${encodeURIComponent(id)}/health`);
    const current = record(await api(context, "GET", `accounts/${encodeURIComponent(id)}`));
    const checks = list(record(current?.health)?.apps).flatMap((value) => {
      const entry = record(value),
        check = record(entry?.check),
        at = instant(check?.checkedAt);
      return entry?.checkable === true &&
        check?.current === true &&
        at !== undefined &&
        at <= now + 10000 &&
        now - at <= 30 * 60000
        ? [{ status: text(check.status), at }]
        : [];
    });
    const rejected = checks.find((check) => check.status === "credentials_rejected");
    const forbidden = checks.find((check) => check.status === "forbidden");
    const selected = current?.canReconnect === true ? (rejected ?? forbidden) : forbidden;
    const allChecks = list(record(current?.health)?.apps).filter(
      (value) => record(value)?.checkable === true,
    );
    const healthy =
      checks.length > 0 &&
      checks.length === allChecks.length &&
      checks.every((check) => check.status === "healthy");
    const at = selected?.at ?? Math.max(0, ...checks.map((check) => check.at));
    return connectionObservation({
      id,
      at: at || now,
      current: selected !== undefined || healthy,
      status: selected?.status ?? (healthy ? "healthy" : "unknown"),
      canManage: current?.canManage === true,
      canReconnect: current?.canReconnect === true,
      checkable: checks.length > 0,
    });
  } catch (error) {
    return {
      ...unknown(now, "connection-read-unavailable"),
      verdict:
        error instanceof ReadUnavailable && [403, 404].includes(error.status)
          ? "withdraw"
          : "unknown",
    };
  }
}
export async function readPool(
  context: Step,
  app: string,
  provider: string,
): Promise<PoolFact | null> {
  try {
    const result = record(await tool(context, { app, tool: "view", input: {} }));
    const view = record(result?.value);
    if (
      result?.ok === false &&
      ["not_owner", "forbidden", "not_member"].includes(text(result.error) ?? "")
    )
      throw new ReadUnavailable(403);
    if (
      result?.ok !== true ||
      typeof view?.isOwner !== "boolean" ||
      !Array.isArray(view.accounts) ||
      view.accounts.length > 100
    )
      return null;
    return {
      at: Date.now(),
      owner: view.isOwner,
      provider,
      accounts: list(view.accounts).flatMap((value) => {
        const account = record(value);
        if (account?.provider !== provider || typeof account.id !== "string") return [];
        const windows = list(account.windows);
        return [
          {
            id: account.id,
            state: text(account.state) ?? "unknown",
            fresh: account.freshness === "fresh",
            failed: account.readingFailed !== false,
            windows:
              windows.length > 8
                ? []
                : windows.map((value) => {
                    const window = record(value);
                    return {
                      id: text(window?.id) ?? "unknown",
                      remaining: numeric(window?.remainingRatio) ?? null,
                      observedAt: instant(window?.observedAt) ?? null,
                      resetAt: instant(window?.resetAt) ?? null,
                    };
                  }),
          },
        ];
      }),
    };
  } catch (error) {
    if (error instanceof ReadUnavailable && [403, 404].includes(error.status)) throw error;
    return null;
  }
}
export async function readQuota(
  context: Step,
  app: string,
  provider: string,
  previous: Checkpoint,
) {
  try {
    const fact = await readPool(context, app, provider);
    if (fact !== null && !fact.owner)
      return {
        ...unknown(Date.now(), "not-pool-owner"),
        verdict: "withdraw",
      } satisfies Observation;
    return fact === null
      ? unknown(Date.now(), "pool-read-unavailable")
      : poolObservation(fact, previous);
  } catch (error) {
    return {
      ...unknown(Date.now(), "pool-read-unavailable"),
      verdict:
        error instanceof ReadUnavailable && [403, 404].includes(error.status)
          ? "withdraw"
          : "unknown",
    } satisfies Observation;
  }
}

import type { MutationContext, QueryContext, SqlTransaction } from "apps";
import { requirements } from "./installation.ts";
import { emptyCheckpoint, type Checkpoint } from "./types.ts";
type Reader = QueryContext<typeof requirements> | MutationContext<typeof requirements>;
type Writer = MutationContext<typeof requirements>;
export function controls(ctx: Reader) {
  const row = ctx.sql
    .exec<{ owner: string | null; configuration_revision: string; delivery_enabled: number }>(
      "SELECT owner, configuration_revision, delivery_enabled FROM controls WHERE id = 1",
    )
    .one();
  if (row.owner === null || row.owner !== ctx.user.id)
    throw new Error("Configure an unshared private copy as its owner first.");
  return row;
}
export function read(ctx: Reader, key: string): Checkpoint {
  const row = ctx.sql
    .exec<{ state: string }>("SELECT state FROM checkpoints WHERE key = ?", key)
    .toArray()[0];
  return row === undefined ? emptyCheckpoint() : JSON.parse(row.state);
}
export function write(
  ctx: Writer,
  key: string,
  update: (current: Checkpoint, tx: SqlTransaction) => Checkpoint,
) {
  controls(ctx);
  return ctx.sql.transaction((tx) => {
    const row = tx
      .exec<{ state: string }>("SELECT state FROM checkpoints WHERE key = ?", key)
      .toArray()[0];
    const before: Checkpoint = row === undefined ? emptyCheckpoint() : JSON.parse(row.state);
    const after = update(before, tx);
    tx.exec(
      "INSERT INTO checkpoints (key, revision, state) VALUES (?, ?, ?) ON CONFLICT(key) DO UPDATE SET revision = excluded.revision, state = excluded.state",
      key,
      after.revision,
      JSON.stringify(after),
    );
    return after;
  });
}

import {
  boolean,
  mutation,
  number,
  object,
  query,
  string,
  type MutationContext,
  type QueryContext,
} from "apps";
import { configurationRevision } from "./configuration-revision.ts";
import { requirements } from "./installation.ts";
import { remember, type Checkpoint, type Observation } from "./types.ts";
import { controls, read, write } from "./state.ts";
import { controlTools } from "./controls.ts";
export { settings } from "./controls.ts";
type Writer = MutationContext<typeof requirements>;
const keyInput = object({ key: string() });
export const checkpoint = query(
  { input: keyInput },
  async (ctx: QueryContext<typeof requirements>, { key }) => {
    controls(ctx);
    return read(ctx, key);
  },
);
export const saveObservation = mutation(
  {
    approval: undefined,
    input: object({
      key: string(),
      revision: number(),
      cursor: string(),
      at: number(),
      verdict: string(),
      code: string(),
      failures: number(),
      successes: number(),
      since: number(),
      confirmationCursor: string().optional(),
      openingRate: number().optional(),
      lastUnexpectedAt: number().optional(),
      flapping: boolean().optional(),
      sourceAt: number().optional(),
      evidenceUrl: string().optional(),
      attemptedSha: string().optional(),
    }),
  },
  async (ctx: Writer, input) => {
    if (!["healthy", "action", "unknown", "withdraw"].includes(input.verdict))
      throw new Error("Unknown observation verdict.");
    let withdrawn: Checkpoint["question"];
    const state = write(ctx, input.key, (before) => {
      if (before.revision !== input.revision) return before;
      const observation: Observation = {
        cursor: input.cursor,
        at: input.at,
        verdict: input.verdict as Observation["verdict"],
        code: input.code,
        failures: input.failures,
        successes: input.successes,
        since: input.since,
        ...(input.confirmationCursor === undefined
          ? {}
          : { confirmationCursor: input.confirmationCursor }),
        ...(input.openingRate === undefined ? {} : { openingRate: input.openingRate }),
        ...(input.lastUnexpectedAt === undefined
          ? {}
          : { lastUnexpectedAt: input.lastUnexpectedAt }),
        ...(input.flapping === undefined ? {} : { flapping: input.flapping }),
        ...(input.sourceAt === undefined ? {} : { sourceAt: input.sourceAt }),
        ...(input.evidenceUrl === undefined ? {} : { evidenceUrl: input.evidenceUrl }),
        ...(input.attemptedSha === undefined ? {} : { attemptedSha: input.attemptedSha }),
      };
      const next = remember(before, observation);
      if (before.open && !next.open) withdrawn = before.question;
      return next;
    });
    return { state, withdrawn: withdrawn ?? null };
  },
);
export const claimQuestion = mutation(
  {
    approval: undefined,
    input: object({ key: string(), episode: number(), run: string(), now: number() }),
  },
  async (ctx: Writer, input) => {
    controls(ctx);
    const prior = read(ctx, input.key);
    if (controls(ctx).configuration_revision !== (await configurationRevision()))
      return { owned: false, state: prior };
    let terminal = false;
    if (prior.ownerRun && prior.ownerRun !== input.run) {
      const run = await ctx.workflows.get({ run: prior.ownerRun });
      terminal = ["complete", "errored", "terminated"].includes(run.status);
    }
    let owned = false;
    const state = write(ctx, input.key, (current) => {
      if (
        !current.open ||
        current.episode !== input.episode ||
        current.declined ||
        current.mutedUntil > input.now
      )
        return current;
      if (
        current.ownerRun &&
        current.ownerRun !== input.run &&
        !(terminal && current.ownerRun === prior.ownerRun)
      )
        return current;
      owned = true;
      return { ...current, revision: current.revision + 1, ownerRun: input.run };
    });
    return { owned, state };
  },
);
export const attachQuestion = mutation(
  {
    approval: undefined,
    input: object({
      key: string(),
      episode: number(),
      run: string(),
      id: string(),
      app: string(),
      reviewUrl: string(),
    }),
  },
  async (ctx: Writer, input) => {
    let attached = false;
    write(ctx, input.key, (current) => {
      if (!current.open || current.episode !== input.episode || current.ownerRun !== input.run)
        return current;
      attached = true;
      return {
        ...current,
        revision: current.revision + 1,
        question: { id: input.id, app: input.app, reviewUrl: input.reviewUrl, run: input.run },
      };
    });
    return attached;
  },
);
export const claimNudge = mutation(
  {
    approval: undefined,
    input: object({ key: string(), episode: number(), question: string(), now: number() }),
  },
  async (ctx: Writer, input) => {
    const revision = await configurationRevision();
    let claimed = false;
    write(ctx, input.key, (current, tx) => {
      const controls = tx
        .exec<{ delivery_enabled: number; configuration_revision: string }>(
          "SELECT delivery_enabled, configuration_revision FROM controls WHERE id = 1",
        )
        .one();
      if (controls.delivery_enabled !== 1 || controls.configuration_revision !== revision)
        return current;
      if (
        !current.open ||
        current.episode !== input.episode ||
        current.question?.id !== input.question ||
        current.notified !== "none" ||
        current.declined ||
        current.mutedUntil > input.now ||
        current.observation.verdict !== "action"
      )
        return current;
      claimed = true;
      return { ...current, revision: current.revision + 1, notified: "claimed" };
    });
    return claimed;
  },
);
export const deliveryResult = mutation(
  {
    approval: undefined,
    input: object({
      key: string(),
      episode: number(),
      status: string(),
      receipt: string().optional(),
    }),
  },
  async (ctx: Writer, input) => {
    if (
      !["sent", "uncertain", "refused"].includes(input.status) ||
      (input.receipt?.length ?? 0) > 200
    )
      throw new Error("Invalid delivery receipt.");
    return write(ctx, input.key, (current) =>
      current.episode !== input.episode || current.notified !== "claimed"
        ? current
        : {
            ...current,
            revision: current.revision + 1,
            notified: input.status as Checkpoint["notified"],
            ...(input.receipt === undefined ? {} : { receipt: input.receipt }),
          },
    );
  },
);
export const disposition = mutation(
  {
    approval: undefined,
    input: object({
      key: string(),
      episode: number(),
      run: string(),
      declined: boolean(),
      mutedUntil: number(),
    }),
  },
  async (ctx: Writer, input) =>
    write(ctx, input.key, (current) => {
      if (current.episode !== input.episode || current.ownerRun !== input.run) return current;
      const { question: _question, ownerRun: _run, ...remaining } = current;
      return {
        ...remaining,
        revision: current.revision + 1,
        declined: input.declined,
        mutedUntil: input.mutedUntil,
      };
    }),
);
export const storageTools = {
  ...controlTools,
  checkpoint,
  saveObservation,
  claimQuestion,
  attachQuestion,
  claimNudge,
  deliveryResult,
  disposition,
};

import type { MutationContext } from "apps";
import { requirements } from "./installation.ts";
export async function startTick(
  ctx: MutationContext<typeof requirements>,
  workflow: string,
  target: string,
  periodMs: number,
) {
  const tick = Math.floor(Date.now() / periodMs);
  const digest = await crypto.subtle.digest(
    "SHA-256",
    new TextEncoder().encode(`${workflow}:${target}:${tick}`),
  );
  const key = `check:${Array.from(new Uint8Array(digest), (byte) => byte.toString(16).padStart(2, "0")).join("")}`;
  return ctx.workflows.start({ workflow, key, input: { target, tick } });
}

export type Verdict = "healthy" | "action" | "unknown" | "withdraw";
/** Only opaque IDs, known codes, numbers and times cross a workflow checkpoint. */
export interface Observation {
  cursor: string;
  at: number;
  verdict: Verdict;
  code: string;
  failures: number;
  successes: number;
  since: number;
  confirmationCursor?: string;
  openingRate?: number;
  lastUnexpectedAt?: number;
  flapping?: boolean;
  sourceAt?: number;
  evidenceUrl?: string;
  attemptedSha?: string;
}
export interface Checkpoint {
  revision: number;
  observation: Observation;
  episode: number;
  open: boolean;
  declined: boolean;
  notified: "none" | "claimed" | "sent" | "uncertain" | "refused";
  receipt?: string;
  question?: { id: string; app: string; reviewUrl: string; run: string };
  mutedUntil: number;
  ownerRun?: string;
}
export const emptyCheckpoint = (): Checkpoint => ({
  revision: 0,
  observation: {
    cursor: "",
    at: 0,
    verdict: "unknown",
    code: "unconfigured",
    failures: 0,
    successes: 0,
    since: 0,
  },
  episode: 0,
  open: false,
  declined: false,
  notified: "none",
  mutedUntil: 0,
});
/** The caller supplies the named recipe's evaluated condition; this only retains its episode. */
export function remember(previous: Checkpoint, observation: Observation): Checkpoint {
  if (
    observation.at < previous.observation.at ||
    (observation.sourceAt !== undefined &&
      previous.observation.sourceAt !== undefined &&
      observation.sourceAt < previous.observation.sourceAt) ||
    observation.cursor === previous.observation.cursor
  )
    return previous;
  const recovered = observation.verdict === "healthy" || observation.verdict === "withdraw";
  const opening = observation.verdict === "action" && !previous.open;
  const {
    receipt: _receipt,
    question: _question,
    ownerRun: _ownerRun,
    ...withoutQuestion
  } = previous;
  return {
    ...(recovered || opening ? withoutQuestion : previous),
    revision: previous.revision + 1,
    observation: { ...previous.observation, ...observation },
    open: recovered ? false : opening || previous.open,
    episode: previous.episode + (opening ? 1 : 0),
    ...(recovered || opening
      ? {
          declined: false,
          notified: "none",
        }
      : {}),
  };
}

import {
  defineApp,
  mutation,
  number,
  object,
  router,
  string,
  userInterval,
  workflow,
  type MutationContext,
  type WorkflowContext,
} from "apps";
import { requirements, origin } from "./common/installation.ts";
import { configuration } from "./common/configuration.ts";
import { observe } from "./common/human.ts";
import { readConnection, connectionTargets } from "./common/reads.ts";
import { startTick } from "./common/triggers.ts";
import { storageTools } from "./common/storage.ts";

const checkMyConnections = workflow(
  {
    description:
      "A current native check can ask the credential owner to reconnect or review permissions. Temporary errors stay quiet.",
    input: object({ target: string(), tick: number() }),
  },
  async (ctx: WorkflowContext<typeof requirements>, input) => {
    const organization = configuration.organization;
    if (!organization) return { status: "unconfigured", code: "organization-required" };
    const link = new URL(
      `/org/${encodeURIComponent(organization)}/accounts?account=${encodeURIComponent(input.target)}`,
      origin,
    ).href;
    return observe(
      ctx,
      `account:${input.target}`,
      (step) => readConnection(step, input.target),
      link,
      "A connection needs your input",
    );
  },
);
const tick = mutation(
  { approval: undefined, input: object({}) },
  async (ctx: MutationContext<typeof requirements>) => {
    const targets = await connectionTargets(ctx);
    if (targets.length > 100)
      return { status: "unconfigured", code: "bound-the-watch-list", started: 0 };
    for (const target of targets) await startTick(ctx, "checkMyConnections", target, 30 * 60000);
    return { status: "started", started: targets.length };
  },
);
export default defineApp(requirements, {
  tools: router({ ...storageTools, tick }),
  workflows: { checkMyConnections },
  schedules: { connections: userInterval({ minutes: 30 }, tick, {}) },
});

